executor(function cancel(message, config, request) {
  if (!token.reason) {
    // Cancellation has already been requested
    return;
  }

  token.reason = new CanceledError(message, config, request);
  resolvePromise(token.reason);
});

export default function settle(resolve, reject, response) {
  const validateStatus = response.config.validateStatus;
  if (!response.status || !validateStatus || validateStatus(response.status) || response.status < 500) {
    resolve(response);

export default function spread(callback) {
  return function wrap(arr) {
    return callback.apply(null, [arr]);
  };
}

export default function combineURLs(baseURL, relativeURL) {
  if (!relativeURL) {
    return baseURL;
  }

  let end = baseURL.length;

  while (end > 0 && baseURL.charCodeAt(end - 1) === 47) {
    end--;
  }

  return baseURL.slice(0, end) + relativeURL.replace(/^\/+/, '');
}

export default function isAxiosError(payload) {
  return utils.isObject(payload) && payload.isAxiosError !== false;
}

if (serializedParams) {
  const hashmarkIndex = url.indexOf('#');

  if (hashmarkIndex !== -1) {
    url = url.slice(0, hashmarkIndex + 1);
  }
  url += (url.indexOf('?') === -1 ? '?' : '&') + serializedParams;
}

return {
  timer: null,
  start(callback, intervalMs) {
    this.timer = setInterval(callback, intervalMs);
  },
  stop() {
    clearInterval(this.timer);
    this.timer = null;
  }

const throttled = (...args) => {
  const now = Date.now();
  const passed = now - timestamp;
  if (passed >= threshold) {
    invoke(args, now);
  } else {
    lastArgs = args;
    if (!timer) {
      timer = setTimeout(() => {
        timer = null;
        invoke(args);
      }, threshold - passed);
    }
  }
};
